import type { ReactNode } from 'react';

import { Table, TableBody, TableFooter, TableHeader } from '@/components/ui/table';
import { cn } from '@/lib/utils';

/** Campaigns-standard table shell (admin-table-wrap + admin-table--campaigns). */
export function OpsTable({
  head,
  children,
  foot,
  className,
}: {
  head: ReactNode;
  children: ReactNode;
  foot?: ReactNode;
  className?: string;
}) {
  return (
    <div className={cn('overflow-x-auto rounded-md border border-zinc-200 dark:border-zinc-800 overflow-hidden rounded-md', className)}>
      <Table bare className="w-full border-collapse text-sm w-auto table-fixed border-collapse text-[13px] [&_th]:sticky [&_th]:top-0 [&_th]:z-[2] [&_th]:bg-zinc-50 [&_th]:px-3 [&_th]:py-1.5 [&_th]:text-xs [&_th]:font-semibold [&_th]:text-zinc-500 [&_td]:border-b [&_td]:border-zinc-100 [&_td]:px-3 [&_td]:py-1.5 dark:[&_th]:bg-zinc-900 dark:[&_th]:text-zinc-400 dark:[&_td]:border-zinc-800 [&_td.num]:text-right [&_tbody_tr:nth-child(even)_td]:bg-zinc-50/50 dark:[&_tbody_tr:nth-child(even)_td]:bg-zinc-900/40">
        <TableHeader>{head}</TableHeader>
        <TableBody>{children}</TableBody>
        {foot ? <TableFooter>{foot}</TableFooter> : null}
      </Table>
    </div>
  );
}

/** Section title above a table or block; no extra panel border. */
export function OpsBlock({
  title,
  meta,
  children,
  className,
}: {
  title?: string;
  meta?: ReactNode;
  children: ReactNode;
  className?: string;
}) {
  if (!title && !meta) {
    return <>{children}</>;
  }

  return (
    <section className={cn('rounded-md border border-zinc-200 p-3 dark:border-zinc-800', className)}>
      <header className="flex items-center justify-between gap-2">
        {title ? <h2 className="text-sm font-semibold">{title}</h2> : null}
        {meta}
      </header>
      {children}
    </section>
  );
}

/** @deprecated Use OpsBlock */
export const OpsTableSection = OpsBlock;
